//! Faithful Rust port of the mapbox `earcut.hpp` polygon triangulation
//! algorithm (std only). Nodes live in an arena (`Vec<Node>`); links are
//! indices into the arena, with `NIL` acting as the null pointer.

const NIL: usize = usize::MAX;

#[derive(Clone)]
struct Node {
    i: u32, // vertex index in the original (flattened) ring order
    x: f64,
    y: f64,
    z: i32, // z-order curve value (hashing for large inputs)
    prev: usize,
    next: usize,
    prev_z: usize, // NIL = null
    next_z: usize, // NIL = null
    steiner: bool,
}

pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut e = Earcut {
        nodes: Vec::new(),
        indices: Vec::new(),
        inv_size: 0.0,
        min_x: 0.0,
        min_y: 0.0,
    };
    e.run(polygon);
    e.indices
}

struct Earcut {
    nodes: Vec<Node>,
    indices: Vec<u32>,
    inv_size: f64,
    min_x: f64,
    min_y: f64,
}

impl Earcut {
    fn run(&mut self, polygon: &[Vec<[f64; 2]>]) {
        if polygon.is_empty() {
            return;
        }

        const THRESHOLD: usize = 80;
        let len = polygon[0].len();

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        if len > THRESHOLD {
            let mut min_x = polygon[0][0][0];
            let mut min_y = polygon[0][0][1];
            let mut max_x = polygon[0][0][0];
            let mut max_y = polygon[0][0][1];

            for p in polygon[0].iter().take(len).skip(1) {
                if p[0] < min_x {
                    min_x = p[0];
                }
                if p[1] < min_y {
                    min_y = p[1];
                }
                if p[0] > max_x {
                    max_x = p[0];
                }
                if p[1] > max_y {
                    max_y = p[1];
                }
            }

            // minX, minY and invSize are later used to transform coords into
            // integers for z-order calculation
            self.min_x = min_x;
            self.min_y = min_y;
            self.inv_size = (max_x - min_x).max(max_y - min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        let outer_node = self.linked_list(&polygon[0], true);
        if outer_node == NIL
            || self.nodes[outer_node].prev == self.nodes[outer_node].next
        {
            return;
        }

        if polygon.len() > 1 {
            self.eliminate_holes(polygon, outer_node);
        }

        self.earcut_linked(outer_node, 0);
    }

    // create a circular doubly linked list from polygon points in the
    // specified winding order
    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
        let mut last = NIL;

        if clockwise == (signed_area(points) > 0.0) {
            for (i, p) in points.iter().enumerate() {
                last = self.insert_node(i as u32, p[0], p[1], last);
            }
        } else {
            for i in (0..points.len()).rev() {
                last = self.insert_node(i as u32, points[i][0], points[i][1], last);
            }
        }

        if last != NIL {
            let next = self.nodes[last].next;
            if equals(&self.nodes[last], &self.nodes[next]) {
                self.remove_node(last);
                last = self.nodes[last].next;
            }
        }
        last
    }

    // eliminate colinear or duplicate points
    fn filter_points(&mut self, start: usize, end: usize) -> usize {
        if start == NIL {
            return start;
        }
        let mut end = if end == NIL { start } else { end };

        let mut p = start;
        loop {
            let mut again = false;

            let p_next = self.nodes[p].next;
            if !self.nodes[p].steiner
                && (equals(&self.nodes[p], &self.nodes[p_next])
                    || self.area(self.nodes[p].prev, p, p_next) == 0.0)
            {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }
        end
    }

    // main ear slicing loop which triangulates a polygon (given as a linked list)
    fn earcut_linked(&mut self, ear: usize, pass: i32) {
        if ear == NIL {
            return;
        }
        let mut ear = ear;

        // interlink polygon nodes in z-order
        if pass == 0 && self.inv_size > 0.0 {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if self.inv_size > 0.0 {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = ear;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find
            // any more ears
            if ear == stop {
                // try filtering points and slicing again
                if pass == 0 {
                    let filtered = self.filter_points(ear, NIL);
                    self.earcut_linked(filtered, 1);

                // if this didn't work, try curing all small
                // self-intersections locally
                } else if pass == 1 {
                    let filtered = self.filter_points(ear, NIL);
                    ear = self.cure_local_intersections(filtered);
                    self.earcut_linked(ear, 2);

                // as a last resort, try splitting the remaining polygon into two
                } else if pass == 2 {
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    // check whether a polygon node forms a valid ear with adjacent nodes
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        let mut p = self.nodes[self.nodes[ear].next].next;
        while p != self.nodes[ear].prev {
            if point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = ax.min(bx).min(cx);
        let min_ty = ay.min(by).min(cy);
        let max_tx = ax.max(bx).max(cx);
        let max_ty = ay.max(by).max(cy);

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;
        while p != NIL && self.nodes[p].z <= max_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;
        while p != NIL && self.nodes[p].z >= min_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    // go through all polygon nodes and cure small local self-intersections
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut p = start;
        let mut start = start;
        loop {
            let a = self.nodes[p].prev;
            let b = self.nodes[self.nodes[p].next].next;

            // a self-intersection where edge (a,p) intersects (p+1,b)
            if !equals(&self.nodes[a], &self.nodes[b])
                && self.intersects(a, p, self.nodes[p].next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                let p_next = self.nodes[p].next;
                self.remove_node(p);
                self.remove_node(p_next);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        p
    }

    // try splitting polygon into two and triangulate them independently
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    a = self.filter_points(a, self.nodes[a].next);
                    c = self.filter_points(c, self.nodes[c].next);

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    // link every hole into the outer loop, producing a single-ring polygon
    // without holes
    fn eliminate_holes(&mut self, polygon: &[Vec<[f64; 2]>], mut outer_node: usize) {
        let len = polygon.len();

        let mut queue = Vec::new();
        for ring in polygon.iter().take(len).skip(1) {
            let list = self.linked_list(ring, false);
            if list != NIL {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }
        queue.sort_by(|&a, &b| {
            self.nodes[a]
                .x
                .partial_cmp(&self.nodes[b].x)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        // process holes from left to right
        for hole in queue {
            self.eliminate_hole(hole, outer_node);
            outer_node = self.filter_points(outer_node, self.nodes[outer_node].next);
        }
    }

    // find a bridge between vertices that connects hole with an outer ring
    // and link it
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge != NIL {
            let b = self.split_polygon(bridge, hole);
            self.filter_points(b, self.nodes[b].next);
        }
    }

    // David Eberly's algorithm for finding a bridge between hole and outer polygon
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        // find a segment intersected by a ray from the hole's leftmost point
        // to the left; segment's endpoint with lesser x will be potential
        // connection point
        loop {
            if hy <= self.nodes[p].y
                && hy >= self.nodes[self.nodes[p].next].y
                && self.nodes[self.nodes[p].next].y != self.nodes[p].y
            {
                let x = self.nodes[p].x
                    + (hy - self.nodes[p].y)
                        * (self.nodes[self.nodes[p].next].x - self.nodes[p].x)
                        / (self.nodes[self.nodes[p].next].y - self.nodes[p].y);
                if x <= hx && x > qx {
                    qx = x;
                    if x == hx {
                        if hy == self.nodes[p].y {
                            return p;
                        }
                        if hy == self.nodes[self.nodes[p].next].y {
                            return self.nodes[p].next;
                        }
                    }
                    m = if self.nodes[p].x < self.nodes[self.nodes[p].next].x {
                        p
                    } else {
                        self.nodes[p].next
                    };
                }
            }
            p = self.nodes[p].next;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        if hx == qx {
            return self.nodes[m].prev;
        }

        // look for points inside the triangle of hole point, segment
        // intersection and endpoint; if there are no points found, we have a
        // valid connection; otherwise choose the point of the minimum angle
        // with the ray as connection point
        let stop = m;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;
        let mut tan_min = f64::INFINITY;

        p = self.nodes[m].next;

        while p != stop {
            if hx >= self.nodes[p].x
                && self.nodes[p].x >= mx
                && hx != self.nodes[p].x
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    self.nodes[p].x,
                    self.nodes[p].y,
                )
            {
                let tan_cur = (hy - self.nodes[p].y).abs() / (hx - self.nodes[p].x);

                if (tan_cur < tan_min
                    || (tan_cur == tan_min && self.nodes[p].x > self.nodes[m].x))
                    && self.locally_inside(p, hole)
                {
                    m = p;
                    tan_min = tan_cur;
                }
            }
            p = self.nodes[p].next;
        }

        m
    }

    // interlink polygon nodes in z-order
    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = self.z_order(x, y);
            }
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let prev_z = self.nodes[p].prev_z;
        self.nodes[prev_z].next_z = NIL;
        self.nodes[p].prev_z = NIL;

        self.sort_list(p);
    }

    // Simon Tatham's linked list merge sort algorithm
    // http://www.chiark.greenend.org.uk/~sgtatham/algorithms/listsort.html
    fn sort_list(&mut self, list: usize) -> usize {
        let mut list = list;
        let mut in_size;
        let mut insize = 1usize;

        loop {
            let mut p = list;
            in_size = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;

            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0usize;
                for _ in 0..insize {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NIL {
                        break;
                    }
                }

                let mut q_size = insize;

                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NIL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NIL {
                        self.nodes[tail].next_z = e;
                    } else {
                        in_size = e;
                    }
                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NIL;

            if num_merges <= 1 {
                return in_size;
            }

            list = in_size;
            insize *= 2;
        }
    }

    // z-order of a point given coords and size of the data bounding box
    fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF_00FF;
        x = (x | (x << 4)) & 0x0F0F_0F0F;
        x = (x | (x << 2)) & 0x3333_3333;
        x = (x | (x << 1)) & 0x5555_5555;

        y = (y | (y << 8)) & 0x00FF_00FF;
        y = (y | (y << 4)) & 0x0F0F_0F0F;
        y = (y | (y << 2)) & 0x3333_3333;
        y = (y | (y << 1)) & 0x5555_5555;

        x | (y << 1)
    }

    // find the leftmost node of a polygon ring
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    // check if a point lies within a convex triangle
    // check if a diagonal between two polygon nodes is valid (lies in polygon
    // interior and does not intersect other edges)
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        self.nodes[self.nodes[a].next].i != self.nodes[b].i
            && self.nodes[self.nodes[a].prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(self.nodes[a].prev, a, self.nodes[b].prev) != 0.0
                    || self.area(a, self.nodes[b].prev, b) != 0.0))
                || (equals(&self.nodes[a], &self.nodes[b])
                    && self.area(self.nodes[a].prev, a, self.nodes[a].next) > 0.0
                    && self.area(self.nodes[b].prev, b, self.nodes[b].next) > 0.0))
    }

    // signed area of a triangle
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        let (p, q, r) = (&self.nodes[p], &self.nodes[q], &self.nodes[r]);
        (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)
    }

    // check if two points are equal
    // check if two segments intersect
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        if (equals(&self.nodes[p1], &self.nodes[q1]) && equals(&self.nodes[p2], &self.nodes[q2]))
            || (equals(&self.nodes[p1], &self.nodes[q2])
                && equals(&self.nodes[p2], &self.nodes[q1]))
        {
            return true;
        }
        (self.area(p1, q1, p2) > 0.0) != (self.area(p1, q1, q2) > 0.0)
            && (self.area(p2, q2, p1) > 0.0) != (self.area(p2, q2, q1) > 0.0)
    }

    // check if a polygon diagonal intersects any polygon segments
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[self.nodes[p].next].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[self.nodes[p].next].i != self.nodes[b].i
                && self.intersects(p, self.nodes[p].next, a, b)
            {
                return true;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }
        false
    }

    // check if a polygon diagonal is locally inside the polygon
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        if self.area(self.nodes[a].prev, a, self.nodes[a].next) < 0.0 {
            self.area(a, b, self.nodes[a].next) >= 0.0
                && self.area(a, self.nodes[a].prev, b) >= 0.0
        } else {
            self.area(a, b, self.nodes[a].prev) < 0.0
                || self.area(a, self.nodes[a].next, b) < 0.0
        }
    }

    // check if the middle point of a polygon diagonal is inside the polygon
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let p_next = self.nodes[p].next;
            if ((self.nodes[p].y > py) != (self.nodes[p_next].y > py))
                && self.nodes[p_next].y != self.nodes[p].y
                && (px
                    < (self.nodes[p_next].x - self.nodes[p].x) * (py - self.nodes[p].y)
                        / (self.nodes[p_next].y - self.nodes[p].y)
                        + self.nodes[p].x)
            {
                inside = !inside;
            }
            p = p_next;
            if p == a {
                break;
            }
        }
        inside
    }

    // link two polygon vertices with a bridge; if the vertices belong to the
    // same ring, it splits polygon into two; if one belongs to the outer ring
    // and another to a hole, it merges it into a single ring
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.new_node(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let b2 = self.new_node(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    // create a node and optionally link it with previous one (in a circular
    // doubly linked list)
    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: usize) -> usize {
        let p = self.new_node(i, x, y);

        if last == NIL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let last_next = self.nodes[last].next;
            self.nodes[p].next = last_next;
            self.nodes[p].prev = last;
            self.nodes[last_next].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    fn new_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node {
            i,
            x,
            y,
            z: 0,
            prev: NIL,
            next: NIL,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        });
        self.nodes.len() - 1
    }

    fn remove_node(&mut self, p: usize) {
        let prev = self.nodes[p].prev;
        let next = self.nodes[p].next;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let prev_z = self.nodes[p].prev_z;
        let next_z = self.nodes[p].next_z;
        if prev_z != NIL {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NIL {
            self.nodes[next_z].prev_z = prev_z;
        }
    }
}

fn equals(p1: &Node, p2: &Node) -> bool {
    p1.x == p2.x && p1.y == p2.y
}

fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) >= (ax - px) * (cy - py)
        && (ax - px) * (by - py) >= (bx - px) * (ay - py)
        && (bx - px) * (cy - py) >= (cx - px) * (by - py)
}

// signed area of a ring
fn signed_area(points: &[[f64; 2]]) -> f64 {
    let mut sum = 0.0;
    let len = points.len();
    if len == 0 {
        return sum;
    }
    let mut j = len - 1;
    for i in 0..len {
        sum += (points[j][0] - points[i][0]) * (points[i][1] + points[j][1]);
        j = i;
    }
    sum
}

