mod earcut;

use std::io::Write;

/// Mimic C `atoi`: skip leading ASCII whitespace, optional sign, consume
/// digits, stop at the first non-digit; no digits -> 0. Parse as i64, then
/// truncate to i32 like strtol -> int conversion.
fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0usize;

    while i < bytes.len()
        && matches!(bytes[i], b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c)
    {
        i += 1;
    }

    let mut sign: i64 = 1;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        if bytes[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }

    let mut val: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        val = val.wrapping_mul(10).wrapping_add((bytes[i] - b'0') as i64);
        i += 1;
    }

    sign.wrapping_mul(val) as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut n: i32 = 1;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let mut ring: Vec<[f64; 2]> = Vec::new();
    let total = n.wrapping_mul(3);
    let mut i: i32 = 0;
    while i < total {
        let angle = 2.0 * std::f64::consts::PI * (i as f64) / (total as f64);
        ring.push([angle.cos(), angle.sin()]);
        i += 1;
    }

    let polygon = vec![ring];
    let indices = earcut::earcut(&polygon);

    let stdout = std::io::stdout();
    let mut w = std::io::BufWriter::new(stdout.lock());
    for idx in indices {
        write!(w, "{} ", idx).unwrap();
    }
    w.flush().unwrap();
}

